// Adventure: 10 worlds of 20 levels. Every level is a hand-drawn formation with its own objective,
// special-brick mix and difficulty; star targets (par shots) come from a bot that played each level
// (see pars.ts, regenerated by scripts/bricks-levels.ts). The same bot sets each level's brick
// health: the hardest the bot can still finish without power-ups, so every level is winnable.
import { COLS, ROWS, type Brick, type BrickType, type Flow, type Goal, type RowGen, type Setup } from "./engine";
import { LEVEL_TUNING } from "./pars";

export const WORLDS = 10;
export const LEVELS_PER_WORLD = 20;
export const LEVEL_COUNT = WORLDS * LEVELS_PER_WORLD;

export type WorldKey = "classic" | "neon" | "crystal" | "volcano" | "frozen" | "ocean" | "desert" | "galaxy" | "shadow" | "frontier";
