type GoalCode = "clear" | "target" | "collect" | "survive" | "formation" | "shots" | "combo";
type Grade = 1 | 2 | 3 | 4 | 5;

interface Entry {
  f: string;
  g: GoalCode;
  /** Difficulty within the world, 1 (gentle) to 5 (the final challenge). */
  d: Grade;
  /** Special bricks dropped into the formation, one every `k` bricks in reading order. */
  sp?: string;
  k?: number;
  mirror?: boolean;
  /** Extra +1 rings spread over empty cells. */
  rings?: number;
  /** Rows pushed down from the top. */
  down?: number;
  /** Survive: rounds; collect/combo: count. */
  n?: number;
}

