export type ObjectiveKind = "clear" | "target" | "collect" | "survive" | "formation" | "shots" | "combo";

export interface LevelDef {
  number: number;
  world: number;
  index: number;
  objective: ObjectiveKind;
  /** The count in the objective (rings, rounds, shots or bricks), when it has one. */
  count: number | null;
  par: number;
  /** Survive levels: score for two and three stars (a round target alone gives one). */
  scoreStars: [number, number] | null;
  setup: Setup;
  initial: { bricks: number; marked: number };
}

/** Starting balls for a level: grows through the worlds and within each world. */
function ballsFor(world: number, index: number, grade: Grade) {
  return Math.round(3 + world * 5.5 + index * 0.6 + grade * 1.5);
}

/** Health per normal brick, relative to the starting balls, by grade. */
const HP_RATIO: Record<Grade, number> = { 1: 0.7, 2: 0.95, 3: 1.2, 4: 1.45, 5: 1.7 };

const LETTER: Record<string, { type: BrickType; hp: number } | undefined> = {
  "#": { type: "std", hp: 1 }, o: { type: "std", hp: 0.5 }, "@": { type: "std", hp: 2 },
  A: { type: "armor", hp: 1 }, B: { type: "bomb", hp: 1 }, H: { type: "hlaser", hp: 1 }, V: { type: "vlaser", hp: 1 },
  "?": { type: "mystery", hp: 1 }, T: { type: "std", hp: 1.6 }, M: { type: "std", hp: 1 },
};

function hash(n: number) {
  let x = (n + 0x9e3779b9) >>> 0;
  x = Math.imul(x ^ (x >>> 16), 0x85ebca6b) >>> 0;
  x = Math.imul(x ^ (x >>> 13), 0xc2b2ae35) >>> 0;
  return (x ^ (x >>> 16)) >>> 0;
}

export interface BoardSpec {
  rows: string[];
  /** Health of a normal brick. */
  base: number;
  sp?: string;
  k?: number;
  mirror?: boolean;
  down?: number;
  /** Mark a target brick when the formation has none drawn. */
  target?: boolean;
  /** Extra +1 rings, and the fewest rings the board must have in all. */
  rings?: number;
  needRings?: number;
  seed: number;
}

/** Turns a drawn formation into bricks and rings. */
export function buildBoard(spec: BoardSpec): { bricks: Omit<Brick, "id">[]; rings: { row: number; col: number }[] } {
  let rows = spec.rows.map((r) => (spec.mirror ? [...r].reverse().join("") : r));
  if (spec.down) rows = [...Array.from({ length: spec.down }, () => "......."), ...rows];
  const grid = rows.map((r) => [...r]);
  // Every k-th plain brick becomes the next of the special bricks, in reading order.
  if (spec.sp && spec.k) {
    let count = 0, next = 0;
    for (let r = 0; r < grid.length; r++) for (let c = 0; c < COLS; c++) {
      if (grid[r][c] !== "#") continue;
      count++;
      if (count % spec.k === 0) grid[r][c] = spec.sp[next++ % spec.sp.length];
    }
  }
  // A target board without a drawn target aims at the highest brick nearest the middle.
  if (spec.target && !grid.some((r) => r.includes("T"))) {
    outer: for (let r = 0; r < grid.length; r++) for (const c of [3, 2, 4, 1, 5, 0, 6]) {
      if (grid[r][c] === "#" || grid[r][c] === "@") { grid[r][c] = "T"; break outer; }
    }
  }
  // Extra rings go in empty cells, spread out deterministically.
  const drawnRings = grid.reduce((sum, r) => sum + r.filter((ch) => ch === "+").length, 0);
  const extraRings = Math.max(spec.rings ?? 0, (spec.needRings ?? 0) - drawnRings);
  if (extraRings > 0) {
    const empty: [number, number][] = [];
    for (let r = 0; r < Math.min(grid.length + 2, ROWS - 2); r++) for (let c = 0; c < COLS; c++) if (!grid[r] || grid[r][c] === ".") empty.push([r, c]);
    let placed = 0, h = hash(spec.seed);
    while (placed < extraRings && empty.length) {
      h = hash(h);
      const [r, c] = empty.splice(h % empty.length, 1)[0];
      while (grid.length <= r) grid.push([..."......."]);
      grid[r][c] = "+";
      placed++;
    }
  }
  const bricks: Omit<Brick, "id">[] = [];
  const rings: { row: number; col: number }[] = [];
  grid.forEach((row, r) => row.forEach((ch, c) => {
    if (ch === "+") { rings.push({ row: r, col: c }); return; }
    const kind = LETTER[ch];
    if (!kind) return;
    const hp = Math.max(1, Math.round(spec.base * kind.hp));
    const armor = kind.type === "armor" ? Math.max(2, Math.round(hp * 0.6)) : 0;
    bricks.push({ row: r, col: c, hp, max: hp, type: kind.type, armor, armorMax: armor, target: ch === "T" || undefined, mark: ch === "M" || undefined });
  }));
  return { bricks, rings };
}

/** Special brick types named by formation letters. */
export function specialsOf(letters: string | undefined): BrickType[] {
  return letters ? [...new Set([...letters].map((ch) => LETTER[ch]?.type).filter((t): t is BrickType => !!t && t !== "std"))] : [];
}

export function levelDef(number: number, tuning?: [number, number]): LevelDef {
  const n = Math.max(1, Math.min(LEVEL_COUNT, Math.round(number)));
  const world = Math.floor((n - 1) / LEVELS_PER_WORLD);
  const index = (n - 1) % LEVELS_PER_WORLD;
  const entry = TABLE[world][index];
  const balls = ballsFor(world, index, entry.d);
  const tuned = LEVEL_TUNING[n - 1];
  const [scale, par] = tuning ?? (tuned ? [tuned[0], tuned[1]] : [1, 6]);
  const botScore = tuned?.[2] ?? 0;
  const base = Math.max(1, Math.round(balls * HP_RATIO[entry.d] * (1 + world * 0.04) * scale));
  const { bricks, rings } = buildBoard({
    rows: F[entry.f] ?? F.first, base, sp: entry.sp, k: entry.k, mirror: entry.mirror, down: entry.down,
    target: entry.g === "target", rings: Math.max(entry.rings ?? 0, 0), needRings: entry.g === "collect" ? (entry.n ?? 0) : 0, seed: n,
  });

  let flow: Flow = "descend";
  let goal: Goal = { kind: "clear" };
  let shotLimit: number | null = null;
  let gen: RowGen | undefined;
  let round: number | undefined;
  switch (entry.g) {
    case "target": goal = { kind: "target" }; break;
    case "formation": goal = { kind: "formation" }; break;
    case "collect": goal = { kind: "collect", count: entry.n ?? rings.length }; break;
    case "combo": goal = { kind: "combo", count: entry.n ?? 8 }; flow = "static"; shotLimit = 8; break;
    case "shots": flow = "static"; shotLimit = Math.max(3, par + 3); break;
    case "survive": {
      flow = "endless";
      goal = { kind: "survive", rounds: entry.n ?? 10 };
      round = balls;
      gen = { hp: HP_RATIO[entry.d] * 0.75 * scale, density: entry.d >= 4 ? 1 : 0, specials: specialsOf(entry.sp) };
      break;
    }
  }
  const setup: Setup = { seed: 70000 + n, balls, bricks, rings, flow, goal, shotLimit, powerups: true, gen, round };
  const count = entry.g === "collect" || entry.g === "survive" || entry.g === "combo" ? (entry.n ?? null) : entry.g === "shots" ? shotLimit : null;
  return {
    number: n, world, index, objective: entry.g, count, par, setup,
    scoreStars: entry.g === "survive" ? [Math.round((botScore * 0.7) / 50) * 50, botScore] : null,
    initial: { bricks: bricks.length, marked: bricks.filter((b) => b.mark).length },
  };
}

/** Stars for a finished level: par shots for three, three more for two, any finish for one.
 * Survive levels go by score instead. */
export function starsFor(def: LevelDef, shots: number, score: number) {
  if (def.scoreStars) return score >= def.scoreStars[1] ? 3 : score >= def.scoreStars[0] ? 2 : 1;
  if (shots <= def.par) return 3;
  if (shots <= def.par + 3) return 2;
  return 1;
}

/** Layout signatures, used by the level check to prove no two levels are the same board. */
export function levelSignature(def: LevelDef) {
  const unit = Math.min(...def.setup.bricks.map((b) => b.hp));
  const cells = def.setup.bricks.map((b) => `${b.row},${b.col},${b.type},${Math.round((b.hp / unit) * 2)},${b.target ? "t" : ""}${b.mark ? "m" : ""}`).sort().join("|");
  return `${def.objective}:${cells}:${def.setup.rings.map((r) => `${r.row},${r.col}`).sort().join("|")}`;
}
